"""Generates auditory_alignment_v3/coverage_train.py: auditory_alignment_v3.local_train.fit_continuous with an optional cap on
training batches per epoch (matched exposure for D_COVERAGE): the sampling pool stays the full training population, the
number of optimizer updates per epoch (and the cosine schedule length) is capped. Declared substitutions only."""
import ast
R = "/home/infres/yinwang/EEG_auditory/"
t = open(R + "auditory_alignment_v3/local_train.py").read(); tree = ast.parse(t); L = t.split("\n")
fc = next("\n".join(L[n.lineno - 1:n.end_lineno]) for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "fit_continuous")
subs = []
def sub(s, a, b):
    assert s.count(a) == 1, a[:60]; subs.append((a.strip()[:80], b.strip()[:80])); return s.replace(a, b)
fc = sub(fc, "def fit_continuous(row, coh, dev, ckpt_prefix, log, sel_weight=None, anchor_weight=None, d=32, grid=1):",
         "def fit_continuous(row, coh, dev, ckpt_prefix, log, sel_weight=None, anchor_weight=None, d=32, grid=1, max_batches=None):")
fc = sub(fc, "    steps_per_epoch = max(1, len(bt.fit) // n_seg)", "    steps_per_epoch = max(1, len(bt.fit) // n_seg) if not max_batches else int(max_batches)")
fc = sub(fc, "        for batch in bt.epoch_batches(rng, n_seg):\n            rws = bt.rows(batch, rng)",
         "        for bi, batch in enumerate(bt.epoch_batches(rng, n_seg)):\n            if max_batches and bi >= max_batches:\n                break\n            rws = bt.rows(batch, rng)")
hdr = '"""GENERATED by private/auditory_alignment_v3/gen_coverage_train.py from auditory_alignment_v3/local_train.py.fit_continuous\nwith these substitutions only:\n' + "".join(f"  - {a!r} -> {b!r}\n" for a, b in subs) + '"""\nfrom .local_train import *  # noqa: F401,F403\nfrom .local_train import GridBatcher, N_SEL, ROWS, Objective, _eff_rank, _kernel_stats, _save_resume, build_encoder, build_head, cs_diag, describe, math, np, os, selection_loss, target_stats, time, torch  # noqa: F401\nfrom auditory_alignment_v2.train import SelectionScore  # noqa: F401\n\n\n'
open(R + "auditory_alignment_v3/coverage_train.py", "w").write(hdr + fc + "\n")
print("written", len(subs))
